lfs_size_t read_size = std::min(hint, size);
lfs_size_t remaining = size;
lfs_off_t current_off = off;
const std::byte* buf_ptr = static_cast<const std::byte*>(buffer);

while (remaining > 0) {
    lfs_size_t chunk_size = std::min(read_size, remaining);
    lfs_cache_t* cache = (current_off == 0) ? pcache : rcache;

    // Read from block device using cache
    int ret = lfs_bd_read(lfs, cache, block, current_off, buf_ptr, chunk_size);
    if (ret != LFS_OK) {
        return ret;
    }

    // Compare with expected data
    if (std::memcmp(buf_ptr, buffer, chunk_size) != 0) {
        return (std::memcmp(buf_ptr, buffer, 1) < 0) ? LFS_CMP_LT : LFS_CMP_GT;
    }

    // Update pointers and counters
    buf_ptr += chunk_size;
    remaining -= chunk_size;
    current_off += chunk_size;
    if (current_off >= lfs->block_size) {
        current_off = 0;
        block++;
    }
}

return LFS_CMP_EQ;
